const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const {chromium} = require('playwright');
const root=process.cwd();
const sandbox={window:{}};
vm.runInNewContext(fs.readFileSync(root+'/js/iqama-timing.js','utf8'),sandbox);
const timing=sandbox.window.AoqatIqamaTiming;
const before={fajr:20,dhuhr:10,asr:15,maghrib:5,isha:30};
const after={fajr:5,dhuhr:15,asr:20,maghrib:15,isha:30};
for(const id of Object.keys(before)){
  const prayers=[{id,startSeconds:1000}],iqama=1000+before[id]*60,end=iqama+after[id]*60;
  assert.equal(timing.state(999,prayers,before,after),null);
  assert.equal(timing.state(1000,prayers,before,after).seconds,before[id]*60);
  assert.equal(timing.state(iqama-1,prayers,before,after).seconds,1);
  assert.equal(timing.state(iqama,prayers,before,after).phase,'elapsed');
  assert.equal(timing.state(iqama,prayers,before,after).seconds,0);
  assert.equal(timing.state(end-1,prayers,before,after).seconds,after[id]*60-1);
  assert.equal(timing.state(end,prayers,before,after),null);
  assert.equal(timing.state(end+3600,prayers,before,after),null);
}
assert.equal(timing.normalize({maghrib:5},before).maghrib,5);
assert.equal(timing.normalize({maghrib:-1},before).maghrib,5);
const maghrib=[{id:'maghrib',startSeconds:17*3600+54*60}];
assert.equal(timing.state(18*3600+2*60+23,maghrib,before,after).seconds,203);
assert.equal(timing.state(18*3600+6*60+19,maghrib,before,after).seconds,439);
assert.equal(timing.state(18*3600+12*60+5,maghrib,before,after).seconds,785);
console.log('PASS: five prayers, countdown/elapsed boundaries, saved settings, screenshot times');
